Voici un exemple de code pour un bot Discord à l'aide de Discord.js v14, qui implémente une commande "bannir" :

```javascript
const { Client, GatewayIntentBits, SlashCommandBuilder } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Ajoutez votre propre clé de bot Discord ici
client.login('Votre clé de bot Discord');

client.on('ready', () => {
  console.log(`Bot ${client.user.tag} est prêt!`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    if (!interaction.memberPermissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n'avez pas les permissions nécessaires pour effectuer cette commande.',
        ephemeral: true,
      });
    }

    const member = interaction.options.getUser('user');
    if (!member) {
      return interaction.reply({
        content: 'Veuillez fournir un utilisateur à bannir.',
        ephemeral: true,
      });
    }

    await interaction.guild.members.ban(member, { days: 7, reason: `Bannissement effectué par ${interaction.user.tag}` });

    return interaction.reply({
      content: `${member.user.tag} a été banni avec succès.`,
      ephemeral: false,
    });
  }
});

const data = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bannit un utilisateur.')
  .addUserOption(option =>
    option
      .setName('user')
      .setDescription('L'utilisateur à bannir')
      .setRequired(true),
  );

client.on('ready', () => {
  client.application.commands.create({
    application_id: client.user.id,
    guild_id: 'Votre ID de serveur Discord',
    name: data.name,
    description: data.description,
    options: data.toJSON(),
  });
});
```

