Voici un cadre de test de haute qualité dans Cypress, qui utilise Docker et utilise également la capacité de Cypress à capturer des captures d'écran et à les enregistrer :

```javascript
// cypress/support/index.js

/**
 * Importez les bibliothèques de Docker et d'ImageMagick.
 * Ces bibliothèques sont utilisées pour capturer des captures d'écran et les enregistrer.
 */
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// Définissez les chemins absolus vers les répertoires de Docker et d'ImageMagick.
const dockerPath = '/usr/bin/docker';
const magickPath = '/usr/bin/convert';

// Définissez les chemins vers les captures d'écran.
const screenshotPath = './screenshots';
const failedScreenshotPath = './failed-screenshots';

// Créez les répertoires s'ils n'existent pas.
if (!fs.existsSync(screenshotPath)) {
  fs.mkdirSync(screenshotPath);
}

if (!fs.existsSync(failedScreenshotPath)) {
  fs.mkdirSync(failedScreenshotPath);
}

/**
 * Fonction de capture de capture d'écran.
 *
 * @param {string} testName - Nom du test actuel.
 * @param {string} filePath - Chemin de sauvegarde de la capture d'écran.
 * @param {boolean} isFailed - Indique si la capture d'écran a échoué.
 */
function captureScreenshot(testName, filePath, isFailed) {
  // Exécutez Docker pour obtenir l'image de l'environnement de test actuel.
  const imageId = execSync(`${dockerPath} images --format='{{.ID}}' --filter='reference={{.}}' ${process.env.CYPRESS_BASE_IMAGE}`).toString().trim();

  // Exécutez ImageMagick pour convertir l'image en PNG.
  const command = `${magickPath} -format png -depth 8 "${imageId}:/app/screenshots/${testName}.png" "${filePath}"`;
  execSync(command);

  // Supprimez l'image générée temporairement.
  execSync(`docker image prune -f ${imageId}`);
}

/**
 * Fonction de gestion des erreurs de capture d'écran.
 *
 * @param {string} testName - Nom du test actuel.
 * @param {Error} error - Erreur de capture d'écran.
 */
function handleScreenshotError(testName, error) {
  console.error(`Erreur de capture d'écran pour "${testName}": ${error.message}`);

  // Enregistrez la capture d'écran échouée.
  captureScreenshot(testName, path.join(failedScreenshotPath, `${testName}.png`), true);
}

/**
 * Fonction de configuration de Cypress.
 *
 * @param {Cypress} Cypress - Instance Cypress.
 */
export function configureCypress(Cypress) {
  Cypress.on('task', {
    captureScreenshot(testName, options) {
      const { fullPage, clip } = options;
      const filePath = path.join(
        screenshotPath,
        `${testName}.${fullPage ? 'full' : 'partial'}${clip ? '-clip' : ''}.png`
      );

      try {
        // Capturez la capture d'écran.
        captureScreenshot(testName, filePath, false);

        // Supprimez les captures d'écran temporaires.
        execSync(`find ${screenshotPath} -mtime +1 -delete`);

        return filePath;
      } catch (error) {
        handleScreenshotError(testName, error);
        return null;
      }
    },
  });
}
```

Voici comment utiliser ce cadre de test :

1. Créez un nouveau projet Cypress et téléchargez le module Cypress Docker.

2. Créez un fichier `.env` à la racine de votre projet Cypress et configurez-le comme suit :

   ```
   CYPRESS_BASE_IMAGE=<IMAGE_NAME>:<TAG>
   ```

   Remplacez `<IMAGE_NAME>` et `<TAG>` par votre propre image Docker.

3. Créez un nouveau fichier `index.js` dans le répertoire `cypress/support` et copiez le contenu de la fonction `configureCypress()` ci-dessus.

4. Exécutez les tests Cypress en utilisant la commande suivante :

   ```
   npx cypress run --spec cypress/integration/**/*.spec.js
   ```

   Les captures d'écran seront enregistrées dans le répertoire `screenshots` et les captures d'écran échouées seront enregistrées dans le répertoire `failed-screenshots`.

5. Pour configurer le chemin de sortie des captures d'écran, vous pouvez définir les variables d'environnement suivantes :

   ```
   CYPRESS_SCREENSHOT_FOLDER=<CUSTOM_FOLDER_NAME>
   CYPRESS_FAILED_SCREENSHOT_FOLDER=<CUSTOM_FOLDER_NAME>
   ```

   Remplacez `<CUSTOM_FOLDER_NAME>` par votre propre chemin de sortie de capture d'écran.

Cela devrait vous fournir une configuration de capture de capture d'écran de haute qualité dans Cypress, utilisant Docker et enregistrant les captures d'écran capturées. Remarquez que vous devez également configurer votre propre image Docker pour exécuter les tests Cypress dans un conteneur Docker. Pour plus d'informations, consultez la documentation Cypress Docker.

